// Remotion's bundler turns imported assets into URLs.
declare module '*.png' {
  const url: string;
  export default url;
}
declare module '*.ttf' {
  const url: string;
  export default url;
}
declare module '*.wav' {
  const url: string;
  export default url;
}
declare module '*.mp4' {
  const url: string;
  export default url;
}
declare module '*.svg' {
  const url: string;
  export default url;
}
